INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp1','choice','{"stem":"\"___ all sounds made by animals serve as language.\"(部分否定‘并非所有…都…’,填否定词)","options":["None","Never","Not","No"],"answer_index":2,"stem_cn":"并非动物发出的所有声音都用作语言。","explanation_cn":"部分否定 Not all …，“并非所有…都…”。✓ Not all sounds serve as language. ✗ No / None / Never:部分否定用 Not all。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp1','choice','{"stem":"\"Not ___ bat uses echolocation in the same way.\"(部分否定‘并非每一…都…’,填‘每一’这个词)","options":["any","every","some","all"],"answer_index":1,"stem_cn":"并非每只蝙蝠都以同样方式回声定位。","explanation_cn":"部分否定 not every …，“并非每一…都…”。✓ Not every bat uses echolocation the same way. ✗ all(与 not 连用意思重复)/ some / any:与 not 构成部分否定用 every。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp1','choice','{"stem":"\"Not all fish ___ detected by their echo alone.\"(部分否定 + 被动,填 be 动词)","options":["was","is","has","are"],"answer_index":3,"stem_cn":"并非所有鱼都能仅凭回声辨认。","explanation_cn":"部分否定 + 被动;主语 fish 复数,be 用 are。✓ Not all fish are detected by their echo. ✗ is(单数)/ was(时态)/ has:复数被动用 are。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp2','choice','{"stem":"\"So ___ born the echo-sounding apparatus now used on ships.\"(so + 倒装,一般过去,填 be 动词)","options":["did","has","was","is"],"answer_index":2,"stem_cn":"回声测深仪就这样诞生了。","explanation_cn":"so + 倒装:So + be 动词 + 主语;叙述过去用 was。✓ So was born the apparatus. ✗ is(时态)/ has / did:此处用 was。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp2','choice','{"stem":"\"So loud was the squeak ___ it echoed off the wall.\"(so … ___:‘如此…以至于’,填引导结果的连词)","options":["which","that","as","than"],"answer_index":1,"stem_cn":"那声尖叫如此响亮,以至在墙上回响。","explanation_cn":"so … that …,“如此…以至于”;引导结果用 that。✓ So loud was the squeak that it echoed. ✗ as / which / than:结果连词用 that。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp2','choice','{"stem":"\"So ___ does the bat fly that the eye can hardly follow it.\"(so + 副词 + 倒装:‘飞得如此快’,填这个副词)","options":["fast","fastest","faster","more fast"],"answer_index":0,"stem_cn":"蝙蝠飞得如此之快,眼睛几乎跟不上。","explanation_cn":"so + 副词 + 倒装:So fast does the bat fly that…;填副词 fast。✓ So fast does the bat fly… ✗ faster / fastest / more fast:此处用原级副词 fast。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp3','choice','{"stem":"\"___ measuring the interval, the depth can be calculated.\"(通过做某事:填引出方式的介词)","options":["In","By","With","On"],"answer_index":1,"stem_cn":"通过测量时间间隔,就能算出深度。","explanation_cn":"by + 动名词表方式,“通过做…”。✓ By measuring the interval… ✗ With / On / In:表方式“通过”用 By。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp3','choice','{"stem":"\"By tapping the hull, the sea bottom can ___ located.\"(情态被动 can + ___ + 过去分词:填中间的词)","options":["is","been","be","being"],"answer_index":2,"stem_cn":"敲击船体,就能测定海底。","explanation_cn":"情态被动 can + be + 过去分词;填中间的 be。✓ the sea bottom can be located. ✗ is / been / being:can 后用原形 be + 过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp3','choice','{"stem":"\"The depth is ___ from the time interval.\"(一般现在被动:is + 过去分词,填过去分词)","options":["calculated","calculating","calculates","calculate"],"answer_index":0,"stem_cn":"深度是根据时间间隔算出的。","explanation_cn":"一般现在时的被动 is + 过去分词。✓ The depth is calculated from the interval. ✗ calculate / calculating / calculates:is 后用过去分词 calculated。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp4','choice','{"stem":"\"Bats locate the insects ___ which they feed.\"(介词 + 关系代词,指物)","options":["at","of","in","on"],"answer_index":3,"stem_cn":"蝙蝠找到它们赖以为食的昆虫。","explanation_cn":"介词 + 关系代词:the insects on which they feed;feed on,故介词用 on。✓ the insects on which they feed. ✗ in / at / of:搭配 feed on。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp4','choice','{"stem":"\"Echolocation is like radar, the principle ___ which is the same.\"(介词 + 关系代词,‘其原理’)","options":["of","in","at","on"],"answer_index":0,"stem_cn":"回声定位像雷达,其原理相同。","explanation_cn":"介词 + 关系代词:the principle of which=“其原理”。✓ radar, the principle of which is the same. ✗ on / at / in:表“其…”用 of which。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp4','choice','{"stem":"\"This is a case ___ which the voice plays a practical role.\"(介词 + 关系代词,‘在其中’)","options":["on","at","in","of"],"answer_index":2,"stem_cn":"这是声音发挥实用作用的一个例子。","explanation_cn":"介词 + 关系代词:a case in which…=“在其中…的例子”。✓ a case in which the voice plays a role. ✗ on / at / of:表“在其中”用 in which。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp5','choice','{"stem":"\"It is possible ___ only to locate a shoal but to name the fish.\"(‘不仅…而且…’的前半,填这个否定词)","options":["not","never","none","no"],"answer_index":0,"stem_cn":"不仅能定位鱼群,还能说出是什么鱼。","explanation_cn":"not only … but …,“不仅…而且…”;前半用 not。✓ not only to locate a shoal but to name the fish. ✗ no / never / none:此结构前半用 not。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp5','choice','{"stem":"\"Every solid object reflects sound, the echo ___ with its size.\"(现在分词作状语,‘随…而变’)","options":["vary","varied","varying","to vary"],"answer_index":2,"stem_cn":"每个实体都反射声音,回声随其大小而变。","explanation_cn":"现在分词作状语,“(回声)随…而变”。✓ the echo varying according to its size. ✗ varied(被动)/ vary / to vary:主动伴随用 -ing。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp5','choice','{"stem":"\"Not only ___ bats emit squeaks, but they also hear the echoes.\"(not only 置于句首引起倒装,填助动词)","options":["have","do","did","are"],"answer_index":1,"stem_cn":"蝙蝠不仅发出尖叫,还能听到回声。","explanation_cn":"Not only 置于句首,句子部分倒装,借助 do + 原形。✓ Not only do bats emit squeaks, but… ✗ are / have / did(时态需一般现在):此处用 do。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp6','choice','{"stem":"\"Something blocking the way is an ___.\"(“障碍物”用哪个词)","options":["obstruction","path","opening","entrance"],"answer_index":0,"stem_cn":"挡住去路的东西。","explanation_cn":"挡住去路的东西是 obstruction。✓ steer clear of any obstruction. ✗ opening 开口;✗ entrance 入口;✗ path 小路——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp6','choice','{"stem":"\"A large group of fish swimming together is a ___.\"(“鱼群”用哪个词)","options":["herd","swarm","shoal","flock"],"answer_index":2,"stem_cn":"一大群一起游的鱼。","explanation_cn":"一大群一起游的鱼是 shoal。✓ a shoal of fish. ✗ flock(禽群)/ herd(兽群)/ swarm(虫群):鱼群用 shoal。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',5,'am4_l7_gp6','choice','{"stem":"\"To send out a sound or signal is to ___ it.\"(“发出”用哪个词)","options":["absorb","emit","store","hide"],"answer_index":1,"stem_cn":"把声音或信号发送出去。","explanation_cn":"把声音或信号发送出去是 emit。✓ bats emit a stream of squeaks. ✗ absorb 吸收;✗ hide 隐藏;✗ store 储存——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',6,NULL,'choice','{"stem":"utilitarian 的意思是:","options":["昂贵的","无用的","实用的,功利的","危险的"],"answer_index":2,"explanation_cn":"utilitarian = 实用的、功利的。✓ a strictly utilitarian purpose 纯粹实用的用途。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',6,NULL,'choice','{"stem":"appreciation 的意思是:","options":["理解,领会","忽视","怀疑","厌恶"],"answer_index":0,"explanation_cn":"appreciation = 理解、领会。✓ a full appreciation of this 充分领会这一点。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',6,NULL,'choice','{"stem":"elapse 的意思是:","options":["加快","(时间)流逝,过去","倒退","停止"],"answer_index":1,"explanation_cn":"elapse = (时间)流逝、过去。✓ the time that must elapse 必须流逝的时间。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',6,NULL,'choice','{"stem":"apparatus 的意思是:","options":["仪器,设备","衣物","玩具","家具"],"answer_index":0,"explanation_cn":"apparatus = 仪器、设备。✓ the echo-sounding apparatus 回声测深仪。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',6,NULL,'choice','{"stem":"obstacle 的意思是:","options":["通道","入口","障碍","桥梁"],"answer_index":2,"explanation_cn":"obstacle = 障碍。✓ a signal strikes an obstacle 信号撞上障碍物。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',6,NULL,'choice','{"stem":"radar 的意思是:","options":["显微镜","雷达","温度计","望远镜"],"answer_index":1,"explanation_cn":"radar = 雷达。✓ often compared with radar 常与雷达相比。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',7,NULL,'cloze','{"stem":"第 1 空","context":"___1___ all animal sounds are language; some are strictly utilitarian. By measuring the interval before an echo, the depth of the sea ___2___ be calculated. So ___3___ born the echo-sounding apparatus. Bats emit squeaks and steer clear of the obstacles ___4___ which they might crash.","blank_no":1,"options":["Not","No","None","Never"],"answer_index":0,"explanation_cn":"部分否定 Not all …。✓ Not all animal sounds are language."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',7,NULL,'cloze','{"stem":"第 2 空","context":"___1___ all animal sounds are language; some are strictly utilitarian. By measuring the interval before an echo, the depth of the sea ___2___ be calculated. So ___3___ born the echo-sounding apparatus. Bats emit squeaks and steer clear of the obstacles ___4___ which they might crash.","blank_no":2,"options":["can","is","has","does"],"answer_index":0,"explanation_cn":"情态被动 can + be + 过去分词。✓ the depth can be calculated."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',7,NULL,'cloze','{"stem":"第 3 空","context":"___1___ all animal sounds are language; some are strictly utilitarian. By measuring the interval before an echo, the depth of the sea ___2___ be calculated. So ___3___ born the echo-sounding apparatus. Bats emit squeaks and steer clear of the obstacles ___4___ which they might crash.","blank_no":3,"options":["was","is","has","did"],"answer_index":0,"explanation_cn":"so + 倒装,So was born…。✓ So was born the echo-sounding apparatus."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',7,NULL,'cloze','{"stem":"第 4 空","context":"___1___ all animal sounds are language; some are strictly utilitarian. By measuring the interval before an echo, the depth of the sea ___2___ be calculated. So ___3___ born the echo-sounding apparatus. Bats emit squeaks and steer clear of the obstacles ___4___ which they might crash.","blank_no":4,"options":["into","on","at","of"],"answer_index":0,"explanation_cn":"介词 + 关系代词:the obstacles into which they might crash;crash into,故介词用 into。✓ obstacles into which they might crash."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',8,NULL,'choice','{"stem":"In what way does echo-location in bats play a utilitarian role?","options":["It warns other bats of danger","It has no real use","It lets them avoid obstacles and find food in the dark","It is used only for singing"],"answer_index":2,"explanation_cn":"录音说蝙蝠的回声定位有实用价值:让它们在黑暗中避开障碍、找到食物。✓ avoid obstacles and find food."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',8,NULL,'choice','{"stem":"How does an echo-sounding apparatus measure the depth of the sea?","options":["By timing how long an echo takes to return from the bottom","By dropping a weighted line","By looking at the water''s color","By using sunlight"],"answer_index":0,"explanation_cn":"录音说回声测深仪靠测量回声从海底返回所需的时间来算出深度。✓ timing the echo."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',8,NULL,'choice','{"stem":"What everyday device is bat echolocation most often compared with?","options":["A camera","Radar","A telephone","A clock"],"answer_index":1,"explanation_cn":"录音说蝙蝠的回声定位最常被拿来与雷达相比,原理相近。✓ radar."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',9,NULL,'choice','{"stem":"你想说\"并非动物发出的所有声音都用作语言\"(部分否定):","options":["No all sounds made by animals serve as language.","Not all sounds made by animals serve as language.","All sounds made by animals not serve as language.","Not all sounds made by animals serves as language."],"answer_index":1,"explanation_cn":"部分否定 Not all …=“并非所有…都…”;Not 放句首、动词 serve 保持原形复数、不用 serves;不把 not 挪到动词后、不用 No all。✓ Not all sounds… serve as language. 场合:说“并非都…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',9,NULL,'choice','{"stem":"你想说\"通过测量时间间隔,就能算出深度\"(by + 动名词 + 被动):","options":["With measuring the interval, the depth can be calculated.","By measure the interval, the depth can be calculated.","By measuring the interval, the depth can calculated.","By measuring the interval, the depth can be calculated."],"answer_index":3,"explanation_cn":"by + 动名词 measuring 表方式,句子用被动 can be calculated;measure 须用 -ing、被动不能丢 be、方式介词用 By 不用 With。✓ By measuring…, the depth can be calculated. 场合:说“通过…做成…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',9,NULL,'choice','{"stem":"你想说\"蝙蝠找到它们赖以为食的昆虫\"(介词 + 关系代词):","options":["Bats locate the insects which they feed.","Bats locate the insects on which they feed on.","Bats locate the insects on which they feed.","Bats locate the insects in which they feed."],"answer_index":2,"explanation_cn":"介词 on 提前 + 关系代词 which(指物);feed on 的 on 放 which 之前,末尾不再重复 on、不用 in、也不能省去 on。✓ the insects on which they feed. 场合:说“它们赖以为食的…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"apparatus 的意思是:","options":["玩具","家具","衣物","仪器,设备"],"answer_index":3,"explanation_cn":"apparatus = 仪器、设备。✓ the echo-sounding apparatus."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"obstacle 的意思是:","options":["通道","桥梁","障碍","入口"],"answer_index":2,"explanation_cn":"obstacle = 障碍。✓ a signal strikes an obstacle."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"\"___ all animal sounds serve as language.\"(部分否定‘并非所有…都…’)","options":["None","Not","No","Never"],"answer_index":1,"stem_cn":"并非所有动物的声音都用作语言。","explanation_cn":"部分否定 Not all …。✓ Not all animal sounds serve as language. ✗ No / None / Never。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"\"By measuring the interval, the depth can ___ calculated.\"(情态被动 can + ___ + 过去分词,填中间的词)","options":["being","been","be","is"],"answer_index":2,"stem_cn":"通过测量间隔,深度就能被算出。","explanation_cn":"情态被动 can + be + 过去分词。✓ the depth can be calculated. ✗ is / been / being。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"\"steer clear of\" 的意思是:","options":["靠近","避开、绕开","撞上","抓住"],"answer_index":1,"explanation_cn":"steer clear of = 避开、绕开。✓ steer clear of any obstruction."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"\"bounce off\" 的意思是:","options":["穿过","沉入","融化","从…弹回"],"answer_index":3,"explanation_cn":"bounce off = 从…弹回。✓ the sound bounces off the sea bottom."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"How were echo-sounding devices first used on ships?","options":["To clean the hull","To measure the depth of the sea by timing echoes","To send radio messages","To power the engines"],"answer_index":1,"passage":"Not all the sounds made by animals serve as a kind of language; some have a strictly practical, utilitarian purpose. To gain a full appreciation of this, it helps to look first at a human invention. Everyone knows that if you shout near a cliff or a high wall, an echo comes back to you. The further off the wall, the longer the time that must elapse before the echo returns. A sound sent down through the water from a ship will bounce off the sea bottom, and by measuring the tiny interval between the sound and the returning echo, the depth of the sea at that point can be calculated. So was born the echo-sounding apparatus that is now fitted to most ships. Every solid object reflects sound, the echo varying according to the size and nature of the object. It is therefore only a short step from finding the sea bottom to finding a shoal of fish; with practice and better equipment, it is now possible not only to locate a shoal but also to tell whether it is herring, cod, or some other kind, simply by the pattern of its echo. Bats do something remarkably similar. It has been found that many bats emit a stream of high squeaks as they fly, and by catching the echoes that bounce back, they can steer clear of any obstruction in the dark and locate the flying insects on which they feed. This echolocation in bats is often compared with radar, the principle of which is much the same: a signal goes out, strikes an obstacle, and returns, and from the returning echo the creature builds a picture of the world it cannot see.","explanation_cn":"课文说回声测深仪最初用于船上:靠测量回声返回的时间来测定海水深度。✓ measure depth by timing echoes."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"What can modern echo devices do besides finding the sea bottom?","options":["Tell what kind of fish a shoal is by its echo","Steer the ship automatically","Count the crew","Predict the weather"],"answer_index":0,"passage":"Not all the sounds made by animals serve as a kind of language; some have a strictly practical, utilitarian purpose. To gain a full appreciation of this, it helps to look first at a human invention. Everyone knows that if you shout near a cliff or a high wall, an echo comes back to you. The further off the wall, the longer the time that must elapse before the echo returns. A sound sent down through the water from a ship will bounce off the sea bottom, and by measuring the tiny interval between the sound and the returning echo, the depth of the sea at that point can be calculated. So was born the echo-sounding apparatus that is now fitted to most ships. Every solid object reflects sound, the echo varying according to the size and nature of the object. It is therefore only a short step from finding the sea bottom to finding a shoal of fish; with practice and better equipment, it is now possible not only to locate a shoal but also to tell whether it is herring, cod, or some other kind, simply by the pattern of its echo. Bats do something remarkably similar. It has been found that many bats emit a stream of high squeaks as they fly, and by catching the echoes that bounce back, they can steer clear of any obstruction in the dark and locate the flying insects on which they feed. This echolocation in bats is often compared with radar, the principle of which is much the same: a signal goes out, strikes an obstacle, and returns, and from the returning echo the creature builds a picture of the world it cannot see.","explanation_cn":"课文说如今的回声设备不仅能定位鱼群,还能凭回声模式判断是鲱鱼、鳕鱼还是别的鱼。✓ tell the kind of fish."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"What do bats send out to find their way in the dark?","options":["Puffs of air","Bright light","High-pitched squeaks","Radio waves"],"answer_index":2,"audio":"Not all the sounds made by animals serve as a kind of language; some have a strictly practical, utilitarian purpose. To gain a full appreciation of this, it helps to look first at a human invention. Everyone knows that if you shout near a cliff or a high wall, an echo comes back to you. The further off the wall, the longer the time that must elapse before the echo returns. A sound sent down through the water from a ship will bounce off the sea bottom, and by measuring the tiny interval between the sound and the returning echo, the depth of the sea at that point can be calculated. So was born the echo-sounding apparatus that is now fitted to most ships. Every solid object reflects sound, the echo varying according to the size and nature of the object. It is therefore only a short step from finding the sea bottom to finding a shoal of fish; with practice and better equipment, it is now possible not only to locate a shoal but also to tell whether it is herring, cod, or some other kind, simply by the pattern of its echo. Bats do something remarkably similar. It has been found that many bats emit a stream of high squeaks as they fly, and by catching the echoes that bounce back, they can steer clear of any obstruction in the dark and locate the flying insects on which they feed. This echolocation in bats is often compared with radar, the principle of which is much the same: a signal goes out, strikes an obstacle, and returns, and from the returning echo the creature builds a picture of the world it cannot see.","explanation_cn":"课文说蝙蝠飞行时会发出一连串高频的吱吱声来探路。✓ high squeaks."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l7',10,NULL,'choice','{"stem":"What do bats do with the echoes that bounce back?","options":["Sing to other bats","Locate obstacles and flying insects","Ignore them","Store them as food"],"answer_index":1,"audio":"Not all the sounds made by animals serve as a kind of language; some have a strictly practical, utilitarian purpose. To gain a full appreciation of this, it helps to look first at a human invention. Everyone knows that if you shout near a cliff or a high wall, an echo comes back to you. The further off the wall, the longer the time that must elapse before the echo returns. A sound sent down through the water from a ship will bounce off the sea bottom, and by measuring the tiny interval between the sound and the returning echo, the depth of the sea at that point can be calculated. So was born the echo-sounding apparatus that is now fitted to most ships. Every solid object reflects sound, the echo varying according to the size and nature of the object. It is therefore only a short step from finding the sea bottom to finding a shoal of fish; with practice and better equipment, it is now possible not only to locate a shoal but also to tell whether it is herring, cod, or some other kind, simply by the pattern of its echo. Bats do something remarkably similar. It has been found that many bats emit a stream of high squeaks as they fly, and by catching the echoes that bounce back, they can steer clear of any obstruction in the dark and locate the flying insects on which they feed. This echolocation in bats is often compared with radar, the principle of which is much the same: a signal goes out, strikes an obstacle, and returns, and from the returning echo the creature builds a picture of the world it cannot see.","explanation_cn":"课文说蝙蝠靠接收弹回的回声来避开障碍、找到赖以为食的飞虫。✓ locate obstacles and insects."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l8',4,2,8,'Trading Standards','贸易标准','强调句(It is … that/who …)、现在完成进行时(have been doing)、情态动词被动(must be done / can be done)+ before 从句、定语从句(that/which,含非限定 which)、complex enough that / simple enough to do + 现在分词作定语(covering)(NCE4 无 KS 页,考点由课文结构自取;原创承载·论富国间贸易摩擦主要源于各国法规与安全标准差异而非关税、两大贸易集团设法避免重复检测的时评·例证自拟·题材无害;美语化 labor/catalog;第四册第8课)','如今,给富国之间的贸易“使绊子”的,主要是各国法规和安全标准的差异,而远非关税。一件符合某个市场标准的器械,在另一市场出售前,仍须经当地检测机构批准;可一台在某国被判定完全安全的机器,极不可能一越过边境就变得危险。于是,两边的企业都会问一个合情合理的问题:既然一次检测就够,何必花钱做两次?多年来,两大贸易集团一直在设法达成一份能免去同一产品重复检测的协议。谈判者态度乐观,可细节复杂到那种程度——一份完整协议或许仍遥遥无期。真正的难处,也是这场争执的根源,在于这些协定该怎么搭建。一方乐意为每个行业单独签一份协定——一份涵盖医疗设备,另一份涵盖电子产品,再一份涵盖玩具——每份都各自敲定。另一方则秉持自己的传统,更愿就宽泛的原则达成一份总协议,那样便可推及许多种商品,日后或许还能延伸到别的国家。在双方就协议的形态谈拢之前,普通制造商只得继续为证明同一件简单的事而付两回钱。','{"q":"Listen and answer — What makes trading between rich countries difficult?","options":["Differences in national regulations and standards","A shortage of goods","High transport costs","Language differences"],"answer_index":0}'::jsonb,'{"title":"强调句 / 现在完成进行时 / 情态被动 + before / 定语从句","intro":"①强调句 It is/was + 被强调部分 + that/who + 其余:It is differences that block trade。②现在完成进行时 have/has + been + doing,强调动作从过去持续到现在:have been trying。③情态动词的被动:must be approved / can be sold;before 引导时间从句。④定语从句 that/which;非限定 which 可指前面整件内容。⑤complex enough that…；simple enough to do；现在分词 covering 作定语。","table":{"headers":["用法","结构","例子"],"rows":[["强调句","It is … that/who …","It is differences that block trade"],["现在完成进行","have been + doing","have been trying to reach a deal"],["情态被动","must/can + be + 过去分词","must be approved before it can be sold"],["现在分词作定语","名词 + doing","a pact covering medical devices"]]},"specialRules":[{"rule":"现在完成进行时=have/has + been + 现在分词,强调“一直在做”;主语单数用 has been。","mark":"have/has been doing"},{"rule":"情态动词后接被动=情态词 + be + 过去分词:must be approved、can be sold。","mark":"must be approved / can be sold"},{"rule":"美式拼写:labor(劳动,英式 labour)、catalog(目录,英式 catalogue)。本课已按美语写。","mark":"labor / catalog"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l8',1,NULL,'These days it is differences in national regulations and safety standards, far more than tariffs, that throw sand in the wheels of trade between wealthy countries. A medical device that meets the standards of one market must still be approved by local testers before it can be sold in another; a machine judged perfectly safe in one country is very unlikely to become dangerous the moment it crosses a border.','如今,给富国之间的贸易“使绊子”的,主要是各国法规和安全标准的差异,而远非关税。一件符合某个市场标准的器械,在另一市场出售前,仍须经当地检测机构批准;可一台在某国被判定完全安全的机器,极不可能一越过边境就变得危险。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l8',2,NULL,'So businesses on both sides ask a reasonable question: why pay for two sets of tests where a single one would do? For years now the two great trading blocs have been trying to reach an agreement that would eliminate the need to test the same product twice.','于是,两边的企业都会问一个合情合理的问题:既然一次检测就够,何必花钱做两次?多年来,两大贸易集团一直在设法达成一份能免去同一产品重复检测的协议。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l8',3,NULL,'Their negotiators are optimistic, yet the details are complex enough that a full deal may still be a long way off. The chief difficulty — and the real source of the dispute — lies in how the accords should be built.','谈判者态度乐观,可细节复杂到那种程度——一份完整协议或许仍遥遥无期。真正的难处,也是这场争执的根源,在于这些协定该怎么搭建。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l8',4,NULL,'One side would happily sign a separate pact for each industry — one accord covering medical equipment, another covering electronics, a third covering toys — each hammered out on its own.','一方乐意为每个行业单独签一份协定——一份涵盖医疗设备,另一份涵盖电子产品,再一份涵盖玩具——每份都各自敲定。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l8',5,NULL,'The other side, true to its traditions, prefers a single agreement on broad principles, which could then be applied to many kinds of goods and perhaps extended to other countries later. Until they agree on the shape of the deal, ordinary manufacturers must go on paying twice to prove the same simple thing.','另一方则秉持自己的传统,更愿就宽泛的原则达成一份总协议,那样便可推及许多种商品,日后或许还能延伸到别的国家。在双方就协议的形态谈拢之前,普通制造商只得继续为证明同一件简单的事而付两回钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
