INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l8','hammer out','',NULL,'/ˈhæmər aʊt/','The two sides hammered out a pact.','双方费力敲定了一份协定。','They hammered out a compromise.','他们谈拢了一个折中方案。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l8','reach a deal','',NULL,'/riːtʃ ə diːl/','They hope to reach a deal soon.','他们希望尽快达成协议。','The two nations reached a deal.','两国达成了协议。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l8','go on doing','',NULL,'/ɡoʊ ɑːn ˈduːɪŋ/','Manufacturers must go on paying twice.','制造商只得继续付两回钱。','She went on working late.','她继续加班到很晚。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l8','apply to','',NULL,'/əˈplaɪ tə/','The principles could be applied to many goods.','这些原则可适用于许多商品。','This rule applies to everyone.','这条规则适用于每个人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp1','choice','{"stem":"\"It is differences in regulations, not tariffs, ___ block trade today.\"(强调句,填连词)","options":["that","who","which","what"],"answer_index":0,"stem_cn":"阻碍贸易的正是法规差异,而非关税。","explanation_cn":"强调句 It is + 被强调部分 + that + 其余;此处被强调的是名词短语,连词用 that。✓ It is differences… that block trade. ✗ what / who(强调物用 that)/ which:强调句连词用 that。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp1','choice','{"stem":"\"It ___ national rules, far more than tariffs, that hinder trade.\"(强调句,一般现在,填 be 动词)","options":["has","is","are","was"],"answer_index":1,"stem_cn":"妨碍贸易的是各国的规章,远甚于关税。","explanation_cn":"强调句 It is/was … that …;叙述当前事实用 is。✓ It is national rules… that hinder trade. ✗ are(强调句 It 后恒用单数 is/was)/ was(时态)/ has:此处用 is。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp1','choice','{"stem":"\"It is the negotiators ___ must settle every point.\"(强调句,强调指人,填连词)","options":["who","which","what","whose"],"answer_index":0,"stem_cn":"必须敲定每一点的正是谈判者。","explanation_cn":"强调句强调的是人(the negotiators),连词可用 who。✓ It is the negotiators who must settle every point. ✗ which(指物)/ what / whose:强调指人用 who。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp2','choice','{"stem":"\"The two blocs have ___ trying to reach a deal for years.\"(现在完成进行 have ___ doing:填中间的词)","options":["being","be","was","been"],"answer_index":3,"stem_cn":"两大贸易集团多年来一直在设法达成协议。","explanation_cn":"现在完成进行时 have + been + doing;中间那个词是 been。✓ have been trying to reach a deal. ✗ be(须用过去分词 been)/ being / was:have 后接 been。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp2','choice','{"stem":"\"Negotiators have been ___ to eliminate double tests.\"(现在完成进行,填 -ing 形式)","options":["work","worked","working","works"],"answer_index":2,"stem_cn":"谈判者一直在努力取消重复检测。","explanation_cn":"现在完成进行时 have been + 现在分词。✓ have been working to eliminate double tests. ✗ work / worked / works:been 后用 -ing 形式 working。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp2','choice','{"stem":"\"For years now they ___ been arguing over standards.\"(现在完成进行,填助动词)","options":["were","have","has","are"],"answer_index":1,"stem_cn":"多年来他们一直在为标准争论不休。","explanation_cn":"现在完成进行时的助动词;主语 they 用 have。✓ they have been arguing. ✗ has(复数主语)/ are / were:they 用 have。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp3','choice','{"stem":"\"A device must ___ approved before sale abroad.\"(情态被动 must + ___ + 过去分词,填中间的词)","options":["is","been","be","being"],"answer_index":2,"stem_cn":"一件器械须先获批才能销往国外。","explanation_cn":"情态动词被动 must + be + 过去分词;中间那个词是 be。✓ A device must be approved. ✗ is / been / being:must 后用原形 be + 过去分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp3','choice','{"stem":"\"It cannot ___ sold until local testers approve it.\"(情态被动 cannot + ___ + 过去分词,填中间的词)","options":["be","been","being","is"],"answer_index":0,"stem_cn":"在当地检测机构批准前,它不能出售。","explanation_cn":"情态动词被动 cannot + be + 过去分词;中间那个词是 be。✓ It cannot be sold until… ✗ is / been / being:cannot 后用原形 be + 过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp3','choice','{"stem":"\"The product must be tested ___ it reaches the market.\"(‘在…之前’,填连词)","options":["while","unless","after","before"],"answer_index":3,"stem_cn":"产品在上市前必须经过检测。","explanation_cn":"“在…之前”引导时间状语从句用 before。✓ must be tested before it reaches the market. ✗ after(其后)/ unless(除非)/ while(当…时):表“之前”用 before。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp4','choice','{"stem":"\"An agreement ___ would end double-testing is hard to reach.\"(定语从句,指物,作主语)","options":["what","who","that","whose"],"answer_index":2,"stem_cn":"一份能终结重复检测的协议很难达成。","explanation_cn":"定语从句先行词 an agreement(物),关系词在从句中作主语,用 that/which,选 that。✓ an agreement that would end double-testing. ✗ who(指人)/ what / whose:指物作主语用 that。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp4','choice','{"stem":"\"They prefer principles, ___ could be applied to many goods.\"(非限定定语从句,指前面内容,填关系词)","options":["that","it","what","which"],"answer_index":3,"stem_cn":"他们更喜欢通用原则,那可以适用于许多商品。","explanation_cn":"非限定定语从句(逗号后)指前面的 principles,关系词用 which(不用 that)。✓ principles, which could be applied to many goods. ✗ that(非限定不用 that)/ what / it:此处用 which。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp4','choice','{"stem":"\"A machine ___ is safe at home stays safe abroad.\"(定语从句,指物,作主语)","options":["what","that","who","whose"],"answer_index":1,"stem_cn":"在本国安全的机器,在国外也一样安全。","explanation_cn":"定语从句先行词 a machine(物),从句中作主语,用 that。✓ A machine that is safe at home… ✗ who(指人)/ what / whose:指物作主语用 that。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp5','choice','{"stem":"\"The details are complex ___ that a deal may be far off.\"(complex … that:‘复杂到…’,填 complex 后这个副词)","options":["enough","very","so","too"],"answer_index":0,"stem_cn":"细节复杂到协议可能遥遥无期。","explanation_cn":"形容词 + enough + that 从句:“…到…以至于”;complex 后这个副词是 enough。✓ complex enough that a deal may be far off. ✗ too / very / so(须搭 that/…):此结构用 enough。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp5','choice','{"stem":"\"One pact, ___ medical devices, was signed first.\"(现在分词作定语,‘涵盖…的’)","options":["to cover","cover","covered","covering"],"answer_index":3,"stem_cn":"一份涵盖医疗器械的协议率先签署。","explanation_cn":"现在分词作后置定语,主动表“涵盖…的”。✓ One pact, covering medical devices,… ✗ covered(被动)/ cover / to cover:主动后置定语用 -ing。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp5','choice','{"stem":"\"The rules are simple ___ to follow without help.\"(simple … to do:‘简单得足以…’,填 simple 后这个副词)","options":["so","too","enough","very"],"answer_index":2,"stem_cn":"这些规则简单得无需帮助就能遵守。","explanation_cn":"形容词 + enough + to do:“…得足以做…”;simple 后这个副词是 enough。✓ simple enough to follow without help. ✗ too(too…to 表否定“太…而不能”)/ so / very:此结构用 enough。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp6','choice','{"stem":"\"A tax on imported goods is a ___.\"(“关税”用哪个词)","options":["wage","fine","salary","tariff"],"answer_index":3,"stem_cn":"对进口货物征收的税。","explanation_cn":"对进口货物征收的税是 tariff(关税)。✓ a tax on imported goods is a tariff. ✗ salary 薪水;✗ fine 罚款;✗ wage 工资——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp6','choice','{"stem":"\"To get rid of something completely is to ___ it.\"(“消除”用哪个词)","options":["hide","create","eliminate","keep"],"answer_index":2,"stem_cn":"把某物彻底去掉。","explanation_cn":"把某物彻底去掉是 eliminate(消除)。✓ to get rid of something completely is to eliminate it. ✗ create 制造;✗ keep 保留;✗ hide 隐藏——都相反或不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',5,'am4_l8_gp6','choice','{"stem":"\"A formal agreement between parties is a ___.\"(“协定”用哪个词)","options":["doubt","pact","rumor","quarrel"],"answer_index":1,"stem_cn":"各方之间的正式协议。","explanation_cn":"各方之间的正式协议是 pact(协定)。✓ a formal agreement between parties is a pact. ✗ quarrel 争吵;✗ doubt 怀疑;✗ rumor 谣言——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',6,NULL,'choice','{"stem":"tariff 的意思是:","options":["罚款","关税","礼物","工资"],"answer_index":1,"explanation_cn":"tariff = 关税。✓ far more than tariffs 远甚于关税。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',6,NULL,'choice','{"stem":"standard 的意思是:","options":["标准","工厂","故事","机器"],"answer_index":0,"explanation_cn":"standard = 标准。✓ the standards of one market 某个市场的标准。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',6,NULL,'choice','{"stem":"eliminate 的意思是:","options":["制造","隐藏","增加","消除,排除"],"answer_index":3,"explanation_cn":"eliminate = 消除、排除。✓ eliminate the need to test twice 免去重复检测。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',6,NULL,'choice','{"stem":"accord 的意思是:","options":["命令","协议,一致","怀疑","争吵"],"answer_index":1,"explanation_cn":"accord = 协议、一致。✓ one accord covering medical equipment 一份涵盖医疗设备的协定。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',6,NULL,'choice','{"stem":"device 的意思是:","options":["食物","建筑","衣物","装置,器械"],"answer_index":3,"explanation_cn":"device = 装置、器械。✓ a medical device 一件医疗器械。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',6,NULL,'choice','{"stem":"optimistic 的意思是:","options":["愤怒的","乐观的","悲观的","疲惫的"],"answer_index":1,"explanation_cn":"optimistic = 乐观的。✓ their negotiators are optimistic 谈判者态度乐观。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',7,NULL,'cloze','{"stem":"第 1 空","context":"It is differences in regulations, not tariffs, ___1___ now block trade. For years the two blocs have ___2___ trying to reach a deal. A device must ___3___ approved before it can be sold abroad. They want an accord ___4___ would end double-testing.","blank_no":1,"options":["that","what","who","which"],"answer_index":0,"explanation_cn":"强调句连词,强调 differences,用 that。✓ It is differences… that now block trade."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',7,NULL,'cloze','{"stem":"第 2 空","context":"It is differences in regulations, not tariffs, ___1___ now block trade. For years the two blocs have ___2___ trying to reach a deal. A device must ___3___ approved before it can be sold abroad. They want an accord ___4___ would end double-testing.","blank_no":2,"options":["been","be","being","was"],"answer_index":0,"explanation_cn":"现在完成进行时 have been + doing,中间用 been。✓ the two blocs have been trying."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',7,NULL,'cloze','{"stem":"第 3 空","context":"It is differences in regulations, not tariffs, ___1___ now block trade. For years the two blocs have ___2___ trying to reach a deal. A device must ___3___ approved before it can be sold abroad. They want an accord ___4___ would end double-testing.","blank_no":3,"options":["be","is","been","being"],"answer_index":0,"explanation_cn":"情态被动 must + be + 过去分词,中间用 be。✓ A device must be approved."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',7,NULL,'cloze','{"stem":"第 4 空","context":"It is differences in regulations, not tariffs, ___1___ now block trade. For years the two blocs have ___2___ trying to reach a deal. A device must ___3___ approved before it can be sold abroad. They want an accord ___4___ would end double-testing.","blank_no":4,"options":["that","who","what","whose"],"answer_index":0,"explanation_cn":"定语从句指物(an accord)作主语,用 that。✓ an accord that would end double-testing."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',8,NULL,'choice','{"stem":"What makes trading between rich countries difficult?","options":["Differences in national regulations and safety standards","A shortage of goods","High tariffs alone","Poor transport"],"answer_index":0,"explanation_cn":"录音说给富国间贸易使绊子的,主要是各国法规与安全标准的差异,而非关税。✓ differences in regulations and standards."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',8,NULL,'choice','{"stem":"What are the two trading blocs trying to achieve?","options":["Higher tariffs","Fewer factories","A deal that would eliminate the need to test products twice","A shared currency"],"answer_index":2,"explanation_cn":"录音说两大集团一直设法达成一份能免去同一产品重复检测的协议。✓ a deal to end double-testing."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',8,NULL,'choice','{"stem":"How do the two sides differ in their approach?","options":["One wants war, the other peace","One wants a separate pact per industry, the other a single deal on principles","One wants no deal at all","They agree completely"],"answer_index":1,"explanation_cn":"录音说一方想按行业逐个签协定,另一方想就宽泛原则签一份总协议。✓ per-industry pact vs. one deal on principles."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',9,NULL,'choice','{"stem":"你想说\"阻碍贸易的正是法规差异,而非关税\"(强调句):","options":["It is differences in regulations, not tariffs, which block trade it.","It is differences in regulations, not tariffs, that block trade.","Is differences in regulations, not tariffs, that block trade.","It is differences in regulations, not tariffs, what block trade."],"answer_index":1,"explanation_cn":"强调句 It is + 被强调部分 + that;It 后用 is、指物连词用 that;不用 which…it 重复、不省 It、不用 what。✓ It is differences…, not tariffs, that block trade. 场合:强调“正是…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',9,NULL,'choice','{"stem":"你想说\"两大贸易集团多年来一直在设法达成协议\"(现在完成进行):","options":["The two blocs have been trying to reach a deal for years.","The two blocs have been try to reach a deal for years.","The two blocs has been trying to reach a deal for years.","The two blocs have being trying to reach a deal for years."],"answer_index":0,"explanation_cn":"现在完成进行时 have been + doing;the two blocs 这类复数用 have、been 不可写成 being、trying 须用 -ing。✓ have been trying. 场合:说“一直在做某事”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',9,NULL,'choice','{"stem":"你想说\"一件器械须先获批才能销往国外\"(情态被动 + before):","options":["A device must approved before it can be sold abroad.","A device must be approve before it can be sold abroad.","A device must be approved before it can be sold abroad.","A device must be approved before it can sold abroad."],"answer_index":2,"explanation_cn":"情态被动 must be approved / can be sold;must 后 be + 过去分词、approve 须用 approved、sold 前不能丢 be。✓ must be approved before it can be sold. 场合:说“须先获批才能…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"tariff 的意思是:","options":["关税","礼物","罚款","工资"],"answer_index":0,"explanation_cn":"tariff = 关税。✓ far more than tariffs."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"eliminate 的意思是:","options":["增加","制造","消除,排除","隐藏"],"answer_index":2,"explanation_cn":"eliminate = 消除、排除。✓ eliminate the need to test twice."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"\"It is differences in rules, not tariffs, ___ block trade.\"(强调句)","options":["which","what","who","that"],"answer_index":3,"stem_cn":"阻碍贸易的是规则差异,而非关税。","explanation_cn":"强调句连词,强调 differences 用 that。✓ It is differences…, not tariffs, that block trade. ✗ what / who / which。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"\"The two blocs have ___ trying to reach a deal.\"(现在完成进行 have ___ doing,填中间的词)","options":["was","be","been","being"],"answer_index":2,"stem_cn":"两大集团一直在设法达成协议。","explanation_cn":"现在完成进行时 have been + doing,中间用 been。✓ the two blocs have been trying. ✗ be / being / was。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"\"hammer out\" 的意思是:","options":["(经努力)达成、敲定","逃走","忽视","打碎"],"answer_index":0,"explanation_cn":"hammer out = (经反复讨价还价)敲定、达成。✓ hammered out a pact."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"\"reach a deal\" 的意思是:","options":["取消交易","拒绝谈判","达成协议","提高价格"],"answer_index":2,"explanation_cn":"reach a deal = 达成协议。✓ hope to reach a deal soon."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"According to the passage, what mainly blocks trade between rich countries today?","options":["Very high tariffs","A lack of ships","Language barriers","Differing national regulations, not tariffs"],"answer_index":3,"passage":"These days it is differences in national regulations and safety standards, far more than tariffs, that throw sand in the wheels of trade between wealthy countries. A medical device that meets the standards of one market must still be approved by local testers before it can be sold in another; a machine judged perfectly safe in one country is very unlikely to become dangerous the moment it crosses a border. So businesses on both sides ask a reasonable question: why pay for two sets of tests where a single one would do? For years now the two great trading blocs have been trying to reach an agreement that would eliminate the need to test the same product twice. Their negotiators are optimistic, yet the details are complex enough that a full deal may still be a long way off. The chief difficulty — and the real source of the dispute — lies in how the accords should be built. One side would happily sign a separate pact for each industry — one accord covering medical equipment, another covering electronics, a third covering toys — each hammered out on its own. The other side, true to its traditions, prefers a single agreement on broad principles, which could then be applied to many kinds of goods and perhaps extended to other countries later. Until they agree on the shape of the deal, ordinary manufacturers must go on paying twice to prove the same simple thing.","explanation_cn":"课文说如今给富国间贸易使绊子的,主要是各国法规差异而非关税。✓ differing regulations, not tariffs."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"How does one side prefer to build the agreement?","options":["A separate pact for each industry","One broad deal on general principles","No agreement at all","A deal only on tariffs"],"answer_index":0,"passage":"These days it is differences in national regulations and safety standards, far more than tariffs, that throw sand in the wheels of trade between wealthy countries. A medical device that meets the standards of one market must still be approved by local testers before it can be sold in another; a machine judged perfectly safe in one country is very unlikely to become dangerous the moment it crosses a border. So businesses on both sides ask a reasonable question: why pay for two sets of tests where a single one would do? For years now the two great trading blocs have been trying to reach an agreement that would eliminate the need to test the same product twice. Their negotiators are optimistic, yet the details are complex enough that a full deal may still be a long way off. The chief difficulty — and the real source of the dispute — lies in how the accords should be built. One side would happily sign a separate pact for each industry — one accord covering medical equipment, another covering electronics, a third covering toys — each hammered out on its own. The other side, true to its traditions, prefers a single agreement on broad principles, which could then be applied to many kinds of goods and perhaps extended to other countries later. Until they agree on the shape of the deal, ordinary manufacturers must go on paying twice to prove the same simple thing.","explanation_cn":"课文说一方乐意为每个行业单独签一份协定。✓ a separate pact per industry."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"Why must some products be tested twice?","options":["The tests are cheap","The makers enjoy it","Each market requires its own approval","The law demands three tests"],"answer_index":2,"audio":"These days it is differences in national regulations and safety standards, far more than tariffs, that throw sand in the wheels of trade between wealthy countries. A medical device that meets the standards of one market must still be approved by local testers before it can be sold in another; a machine judged perfectly safe in one country is very unlikely to become dangerous the moment it crosses a border. So businesses on both sides ask a reasonable question: why pay for two sets of tests where a single one would do? For years now the two great trading blocs have been trying to reach an agreement that would eliminate the need to test the same product twice. Their negotiators are optimistic, yet the details are complex enough that a full deal may still be a long way off. The chief difficulty — and the real source of the dispute — lies in how the accords should be built. One side would happily sign a separate pact for each industry — one accord covering medical equipment, another covering electronics, a third covering toys — each hammered out on its own. The other side, true to its traditions, prefers a single agreement on broad principles, which could then be applied to many kinds of goods and perhaps extended to other countries later. Until they agree on the shape of the deal, ordinary manufacturers must go on paying twice to prove the same simple thing.","explanation_cn":"录音说一件器械在另一市场出售前仍须经当地检测机构批准,故要测两次。✓ each market requires its own approval."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l8',10,NULL,'choice','{"stem":"How do the negotiators feel about reaching a deal?","options":["Certain it will fail","Completely indifferent","Angry at each other","Optimistic, though the details are complex"],"answer_index":3,"audio":"These days it is differences in national regulations and safety standards, far more than tariffs, that throw sand in the wheels of trade between wealthy countries. A medical device that meets the standards of one market must still be approved by local testers before it can be sold in another; a machine judged perfectly safe in one country is very unlikely to become dangerous the moment it crosses a border. So businesses on both sides ask a reasonable question: why pay for two sets of tests where a single one would do? For years now the two great trading blocs have been trying to reach an agreement that would eliminate the need to test the same product twice. Their negotiators are optimistic, yet the details are complex enough that a full deal may still be a long way off. The chief difficulty — and the real source of the dispute — lies in how the accords should be built. One side would happily sign a separate pact for each industry — one accord covering medical equipment, another covering electronics, a third covering toys — each hammered out on its own. The other side, true to its traditions, prefers a single agreement on broad principles, which could then be applied to many kinds of goods and perhaps extended to other countries later. Until they agree on the shape of the deal, ordinary manufacturers must go on paying twice to prove the same simple thing.","explanation_cn":"录音说谈判者态度乐观,可细节复杂到协议或许仍遥遥无期。✓ optimistic though complex."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
